// 여기서 전체 앱이 백엔드 없이도 돌아가도록 가짜 응답을 관리
import { buildKey } from "./mockUtil";

// 여기가 네 "가짜 DB"
const MOCK_DB = {
  // 품목 리스트 (생산계획 페이지 등)
  "/plan/itemlist/main": [
    { itemNo: 1, itemName: "데모 상품 A" },
    { itemNo: 2, itemName: "데모 상품 B" },
    { itemNo: 3, itemName: "데모 상품 C" },
  ],

  // 예측 시계열 데이터 (수요예측/ForecastCard 등)
  "/forecast/series?itemNo=1&h=12": {
    itemNo: 1,
    horizon: 12,
    series: [
      { ym: "2025-01", qty: 120 },
      { ym: "2025-02", qty: 140 },
      { ym: "2025-03", qty: 160 },
      { ym: "2025-04", qty: 155 },
      { ym: "2025-05", qty: 170 },
    ],
  },

  // 월별 매출 (대시보드 차트)
  "/sales/monthly?ym=2025-01": [
    { ym: "2025-01", totalSales: 1230000 },
    { ym: "2025-02", totalSales: 1500000 },
    { ym: "2025-03", totalSales: 990000 },
    { ym: "2025-04", totalSales: 1710000 },
  ],

  // 상위 품목 판매량 Top N
  "/sales/item-qty-monthly?ym=2025-01": [
    { itemName: "데모 상품 A", qty: 120 },
    { itemName: "데모 상품 B", qty: 95 },
    { itemName: "데모 상품 C", qty: 60 },
    { itemName: "데모 상품 D", qty: 42 },
  ],

  // 월/품목 상세 전체
  "/sales/item-qty-monthly-all": [
    { ym: "2025-01", itemName: "데모 상품 A", qty: 120 },
    { ym: "2025-01", itemName: "데모 상품 B", qty: 80 },
    { ym: "2025-02", itemName: "데모 상품 A", qty: 140 },
    { ym: "2025-02", itemName: "데모 상품 B", qty: 90 },
    { ym: "2025-03", itemName: "데모 상품 A", qty: 160 },
    { ym: "2025-03", itemName: "데모 상품 B", qty: 88 },
  ],

  // 주문 리스트 (구매/판매 화면에서 쓸 리스트)
  "/order/list": [
    {
      orderNo: "O-2025-001",
      buyer: "고객 A",
      item: "데모 상품 A",
      qty: 100,
      dueDate: "2025-11-01",
      status: "CONFIRMED",
    },
    {
      orderNo: "O-2025-002",
      buyer: "고객 B",
      item: "데모 상품 B",
      qty: 60,
      dueDate: "2025-11-03",
      status: "PENDING",
    },
  ],

  // 재고 리스트 (창고/재고 페이지)
  "/stock/list": [
    {
      itemNo: "MAT-001",
      itemName: "원자재-A",
      qty: 320,
      unit: "EA",
      loc: "창고-1",
      safeQty: 200,
    },
    {
      itemNo: "MAT-002",
      itemName: "원자재-B",
      qty: 140,
      unit: "EA",
      loc: "창고-2",
      safeQty: 100,
    },
  ],
};

// 공통 응답기
function lookup(path, opts = {}) {
  const key = buildKey(path, opts);
  if (Object.prototype.hasOwnProperty.call(MOCK_DB, key)) {
    return structuredClone(MOCK_DB[key]);
  }

  console.warn("[mockBackend] no mock data for", key);
  // 기본값은 빈 배열로 돌려서 map() 호출하는 컴포넌트 에러 방지
  return [];
}

// 아래 함수들이 axios_api에서 호출
// axios_api는 { data: mockGet(...) } 형태로 래핑
// 순수 데이터만 반환
export function mockGet(path, opts = {}) {
  return lookup(path, opts);
}

export function mockPost(path, body, opts = {}) {
  console.log("[mockPost] pretend create:", path, body);
  return { success: true, message: "데모 모드: 생성된 것으로 처리했습니다." };
}

export function mockPut(path, body, opts = {}) {
  console.log("[mockPut] pretend update:", path, body);
  return { success: true, message: "데모 모드: 수정된 것으로 처리했습니다." };
}

export function mockDelete(path, opts = {}) {
  console.log("[mockDelete] pretend delete:", path);
  return { success: true, message: "데모 모드: 삭제된 것으로 처리했습니다." };
}
